// CC0: Progress bar meme
//  There's kind of a C# meme going on twitter about this tweet:
//  https://twitter.com/mariusbancila/status/1615710620204077056?s=20&t=Miioq51z6b8eSJ_6Gu4ubg
//  The community is divided. Does the code suck or is it good?
//  So I implemented the progress bar in GLSL for fun.
//  I am kind of hoping Fabrice shows up and gives it a minification treatment so all
//  readability disappears :)

#define TIME        iTime
#define RESOLUTION  iResolution

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
  const float sz  = 0.25;
  const float hsz = sz*0.5;

  vec2 q = fragCoord/RESOLUTION.xy;
  vec2 p = -1. + 2. * q;
  vec2 pp = p;
  p.x *= RESOLUTION.x/RESOLUTION.y;

  float progress = smoothstep(-0.9, 0.9, sin(TIME));

  float aa = 2.0/RESOLUTION.y;

  vec2 p0 = p;
  p0.x += sz*4.5;

  float n0 = floor((p0.x + hsz)/sz);
  p0.x = mod(p0.x + hsz, sz) - hsz;

  vec3 col = vec3(1.0);
  if (n0 >= 0.0 && n0 < 10.0) {
    float d0 = length(p0)-sz*0.4;
    vec3 fcol = n0 >= 10.0*progress ? vec3(0.9) : vec3(0.125, 0.33, 0.9);
    col = mix(col, vec3(0.0), smoothstep(aa, -aa, d0));
    col = mix(col, fcol, smoothstep(aa, -aa, d0+0.02*sz));
  }
  col *= smoothstep(1.75, 0., length(pp));
  col = sqrt(col);

  fragColor = vec4(col, 1.0);
}
